const input = $input.first().json;
const data = input.body || input;

const allInputs = $input.all();
console.log('✅ Agent 2: Received', allInputs.length, 'item(s)');

if (allInputs.length !== 1) {
  console.error('⚠️ AGENT 2 ERROR: Expected 1 item, got', allInputs.length);
}

const searchQuery = data.topic || 'AI trends';
const hasSourceUrl = !!(data.url && data.url.trim());

console.log('✅ Agent 2: Topic:', data.topic);
console.log('✅ Agent 2: Has source URL:', hasSourceUrl);

return [{
  json: {
    topic: data.topic,
    url: data.url || '',
    style: data.style,
    length: data.length,
    angle: data.angle,
    searchQuery: searchQuery,
    hasSourceUrl: hasSourceUrl
  }
}];

const html = $input.first().json.data || $input.first().json || '';
const parseData = $("Parse Input").first().json;

// Convert HTML to plain text
function htmlToText(html) {
  if (typeof html !== 'string') return '';

  let text = html;

  // Remove script and style tags with content
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
  text = text.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
  text = text.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');

  // Replace common block elements with newlines
  text = text.replace(/<\/(p|div|h[1-6]|li|tr|br)[^>]*>/gi, '\n');
  text = text.replace(/<br[^>]*>/gi, '\n');

  // Remove all remaining HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode HTML entities
  text = text.replace(/&nbsp;/g, ' ');
  text = text.replace(/&amp;/g, '&');
  text = text.replace(/&lt;/g, '<');
  text = text.replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");

  // Clean up whitespace
  text = text.replace(/\s+/g, ' ');
  text = text.replace(/\n\s*\n/g, '\n\n');
  text = text.trim();

  // Limit length to avoid token limits
  if (text.length > 8000) {
    text = text.substring(0, 8000) + '...';
  }

  return text;
}

const sourceContent = htmlToText(html);
console.log('✅ Agent 2: Extracted', sourceContent.length, 'chars from source URL');

return [{
  json: {
    ...parseData,
    sourceContent: sourceContent,
    sourceUrl: parseData.url
  }
}];

// No source URL, just pass through with empty sourceContent
const parseData = $("Parse Input").first().json;

return [{
  json: {
    ...parseData,
    sourceContent: '',
    sourceUrl: ''
  }
}];

const inputData = $input.first().json;
const serpResults = inputData.organic_results || [];

// Get source data from whichever path executed
let sourceData;
try {
  sourceData = $("Extract Source Content").first()?.json;
} catch(e) {
  sourceData = null;
}
if (!sourceData) {
  try {
    sourceData = $("No Source Content").first()?.json;
  } catch(e) {
    sourceData = $("Parse Input").first().json;
  }
}

const sources = [];
const snippets = [];
const urlsToFetch = [];

for (let i = 0; i < Math.min(serpResults.length, 5); i++) {
  const result = serpResults[i];
  if (result.link && result.title) {
    sources.push({
      url: result.link,
      title: result.title
    });
    // Only fetch top 3 for deeper content
    if (i < 3 && result.link) {
      urlsToFetch.push(result.link);
    }
  }
  if (result.snippet) {
    snippets.push(`${result.title}: ${result.snippet}`);
  }
}

console.log('✅ Agent 2: Found', sources.length, 'sources,', urlsToFetch.length, 'to fetch deeply');

return [{
  json: {
    sources: sources,
    snippets: snippets,
    urlsToFetch: urlsToFetch,
    topic: sourceData.topic,
    style: sourceData.style,
    length: sourceData.length,
    angle: sourceData.angle,
    sourceContent: sourceData.sourceContent || '',
    sourceUrl: sourceData.sourceUrl || ''
  }
}];

// Split URLs for fetching
const data = $input.first().json;
const urls = data.urlsToFetch || [];

if (urls.length === 0) {
  // No URLs to fetch, pass through with empty fetchedContent
  return [{
    json: {
      ...data,
      fetchedContent: [],
      hasUrlsToFetch: false
    }
  }];
}

// Return each URL as separate item for fetching
return urls.map((url, index) => ({
  json: {
    urlToFetch: url,
    urlIndex: index,
    originalData: data,
    hasUrlsToFetch: true
  }
}));

const items = $input.all();
const splitData = $("Split URLs to Fetch").all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const html = item.json.data || (typeof item.json === 'string' ? item.json : '') || '';
  const urlData = splitData[i]?.json || {};
  const urlToFetch = urlData.urlToFetch || '';

  // Convert HTML to plain text
  function htmlToText(html) {
    if (typeof html !== 'string') return '';

    let text = html;

    // Remove script and style tags with content
    text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
    text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
    text = text.replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '');
    text = text.replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '');
    text = text.replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '');

    // Replace common block elements with newlines
    text = text.replace(/<\/(p|div|h[1-6]|li|tr|br)[^>]*>/gi, '\n');
    text = text.replace(/<br[^>]*>/gi, '\n');

    // Remove all remaining HTML tags
    text = text.replace(/<[^>]+>/g, ' ');

    // Decode HTML entities
    text = text.replace(/&nbsp;/g, ' ');
    text = text.replace(/&amp;/g, '&');
    text = text.replace(/&lt;/g, '<');
    text = text.replace(/&gt;/g, '>');
    text = text.replace(/&quot;/g, '"');
    text = text.replace(/&#39;/g, "'");

    // Clean up whitespace
    text = text.replace(/\s+/g, ' ');
    text = text.replace(/\n\s*\n/g, '\n\n');
    text = text.trim();

    // Limit length
    if (text.length > 3000) {
      text = text.substring(0, 3000) + '...';
    }

    return text;
  }

  const content = htmlToText(html);
  if (content.length > 100) {
    results.push({
      url: urlToFetch,
      content: content
    });
  }
}

const originalData = splitData[0]?.json?.originalData || {};

console.log('✅ Agent 2: Fetched content from', results.length, 'URLs');

return [{
  json: {
    fetchedContent: results,
    sources: originalData.sources || [],
    snippets: originalData.snippets || [],
    topic: originalData.topic,
    style: originalData.style,
    length: originalData.length,
    angle: originalData.angle,
    sourceContent: originalData.sourceContent || '',
    sourceUrl: originalData.sourceUrl || ''
  }
}];

// No URLs to fetch path - just pass through
const data = $input.first().json;

return [{
  json: {
    fetchedContent: [],
    sources: data.sources || [],
    snippets: data.snippets || [],
    topic: data.topic,
    style: data.style,
    length: data.length,
    angle: data.angle,
    sourceContent: data.sourceContent || '',
    sourceUrl: data.sourceUrl || ''
  }
}];

// Get data from whichever path executed
let data;
try {
  data = $("Extract Fetched Content").first()?.json;
} catch(e) {
  data = null;
}
if (!data || !data.topic) {
  try {
    data = $("No URLs to Fetch").first()?.json;
  } catch(e) {
    data = null;
  }
}

if (!data) {
  throw new Error('No data received from either path');
}

const topic = data.topic;
const sourceContent = data.sourceContent || '';
const sourceUrl = data.sourceUrl || '';
const snippets = data.snippets || [];
const sources = data.sources || [];
const fetchedContent = data.fetchedContent || [];

// Build comprehensive research summary
let researchSummary = `# Research on: ${topic}\n\n`;

// Add source article content if available
if (sourceContent && sourceContent.length > 100) {
  researchSummary += `## Primary Source Content\n`;
  researchSummary += `Source: ${sourceUrl}\n\n`;
  researchSummary += sourceContent.substring(0, 4000);
  researchSummary += '\n\n';
}

// Add search result snippets
if (snippets.length > 0) {
  researchSummary += `## Search Result Summaries\n\n`;
  snippets.forEach((snippet, i) => {
    researchSummary += `${i + 1}. ${snippet}\n\n`;
  });
}

// Add fetched article content
if (fetchedContent.length > 0) {
  researchSummary += `## Detailed Source Content\n\n`;
  fetchedContent.forEach((item, i) => {
    researchSummary += `### Source ${i + 1}: ${item.url}\n\n`;
    researchSummary += item.content;
    researchSummary += '\n\n';
  });
}

// Trim if too long (to avoid token limits in Agent 3)
if (researchSummary.length > 20000) {
  researchSummary = researchSummary.substring(0, 20000) + '\n\n[Content truncated due to length]';
}

console.log('✅ Agent 2: Built research summary with', researchSummary.length, 'chars');
console.log('   - Source content:', sourceContent.length > 0 ? 'Yes' : 'No');
console.log('   - Snippets:', snippets.length);
console.log('   - Fetched articles:', fetchedContent.length);

return [{
  json: {
    researchSummary: researchSummary,
    sources: sources,
    topic: topic,
    style: data.style,
    length: data.length,
    angle: data.angle
  }
}];
